    private void btnInicarSesionActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnInicarSesionActionPerformed
        try{
            Trabajador objUsuario = new Trabajador();
            if(objUsuario.autenticar(this.txtUsuario.getText(),
                    this.txtContrasena.getText())){
                FmrMenuPrincipal formulario = new FmrMenuPrincipal(objUsuario);
                formulario.setVisible(true);
                this.dispose();
                formulario.setExtendedState(javax.swing.JFrame.MAXIMIZED_BOTH);            
            }else{
                this.msjError.setText("Credenciales inválidas");
            }
        }catch(Exception e){
            this.msjError.setText(e.getMessage());
        }
    }//GEN-LAST:event_btnInicarSesionActionPerformed

